<script setup>
import { computed, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useEvents } from '@/composables/useEvents'
import AppModal from '@/components/ui/AppModal.vue'
import RegistrationForm from '@/components/event/RegistrationForm.vue'
import RegistrationSummary from '@/components/event/RegistrationSummary.vue'
import RegistrationReceipt from '@/components/event/RegistrationReceipt.vue'
const route=useRoute(),router=useRouter(),{getEventById,isUserRegistered,registerAttendee}=useEvents()
const event=computed(()=>getEventById(route.params.id)), existing=computed(()=>isUserRegistered(route.params.id))
const draftKey=computed(()=>`gatherly_registration_draft_${route.params.id}`), clearToken=ref(0), error=ref(''), modal=ref(false), registration=ref(null)
const blocked=computed(()=>!event.value||event.value.done||existing.value||event.value.seatsLeft<=0)
const blockedText=computed(()=>!event.value?'This event could not be found.':event.value.done?'Registration for this event is closed.':existing.value?'You already have a ticket for this event.':event.value.seatsLeft<=0?'This event is sold out.':'')
function submit(attendee){const result=registerAttendee(route.params.id,attendee);if(!result.ok){error.value=result.message;return}error.value='';registration.value=result.registration;clearToken.value++;modal.value=true}
function goTicket(){router.push(`/your-events/${registration.value.id}`)}
function discard(){modal.value=false;clearToken.value++;router.push(`/browse/events/${route.params.id}`)}
</script>
<template><main class="registration-page"><RouterLink :to="event?`/browse/events/${event.id}`:'/browse/events'" class="back">← Back to event</RouterLink><header class="heading"><span class="eyebrow">SAVE YOUR SPOT</span><h1>Event registration</h1><p>Share a few details with the organizer to reserve your place.</p></header><section v-if="blocked" class="blocked"><span class="blocked-icon">i</span><h2>{{blockedText}}</h2><p v-if="event">{{event.title}} · {{event.seatsLeft}} spots remaining</p><RouterLink v-if="existing" to="/your-events" class="primary-link">View your tickets</RouterLink><RouterLink v-else to="/browse/events" class="primary-link">Browse events</RouterLink></section><div v-else class="registration-layout"><RegistrationSummary :event="event"/><div><div v-if="error" class="error" role="alert">{{error}}</div><RegistrationForm :key="draftKey" :draft-key="draftKey" :clear-token="clearToken" @submit="submit" @cancel="$router.push(`/browse/events/${event.id}`)" @cancel-request="modal=true"/></div></div><AppModal :isopen="modal" :title="registration?'Registration confirmed':'Discard your details?'" :message="registration?'':'Your information has been saved on this device. Are you sure you want to leave this form?'" :confirm-text="registration?'View ticket':'Discard details'" :cancel-text="registration?'Continue':'Keep editing'" @confirm="registration?goTicket():discard()" @close="modal=false"><RegistrationReceipt v-if="registration" :registration="registration" :event="event"/><p v-else class="modal-note">Your information has been saved on this device. Do you want to discard it and leave this form?</p><template v-if="registration" #footer><button class="modal-button modal-button--quiet" @click="router.push('/your-events')">Your Events</button><button class="modal-button modal-button--danger" @click="goTicket">View ticket</button></template></AppModal></main></template>
<style scoped>.registration-page{max-width:1100px;margin:auto;color:#211d47}.back{display:inline-block;margin:0 0 1.2rem;color:#77768a;text-decoration:none;font-size:.8rem;font-weight:700}.heading{margin-bottom:1.3rem}.eyebrow{color:#9997aa;font-size:.65rem;font-weight:800;letter-spacing:.15em}.heading h1{margin:.35rem 0;font-size:clamp(1.7rem,4vw,2.35rem);letter-spacing:-.04em}.heading p{margin:0;color:#858397;font-size:.87rem}.registration-layout{display:grid;grid-template-columns:minmax(260px,.8fr) minmax(0,1.2fr);align-items:start;gap:1.2rem}.error{margin-bottom:.8rem;padding:.8rem 1rem;border-radius:10px;color:#a8354d;background:#fff0f2;font-size:.78rem}.blocked{display:grid;justify-items:center;padding:4rem 1rem;border:1px solid #eeedf4;border-radius:18px;background:#fff;text-align:center}.blocked-icon{display:grid;place-items:center;width:48px;height:48px;border-radius:16px;color:#6748ed;background:#f0edff;font-weight:800}.blocked h2{margin:1rem 0 .35rem;font-size:1.15rem}.blocked p{color:#858397;font-size:.8rem}.primary-link{padding:.7rem .9rem;border-radius:10px;color:white;background:#6748ed;text-decoration:none;font-size:.78rem;font-weight:750}.modal-button{min-height:44px;padding:0 1rem;border:0;border-radius:11px;font:inherit;font-size:.78rem;font-weight:750;cursor:pointer}.modal-button--quiet{color:#68677a;background:#f3f3f8}.modal-button--danger{color:#fff;background:#6748ed}@media(max-width:750px){.registration-layout{grid-template-columns:1fr}}</style>
